// Regenerates sdk/abi.ts from the compiled artifact. Run after `npm run build`.
import { readFileSync, writeFileSync } from "node:fs";

const artifact = JSON.parse(
  readFileSync("artifacts/contracts/SpendGuardVault.sol/SpendGuardVault.json", "utf8"),
);
const token = JSON.parse(readFileSync("artifacts/contracts/test/TestToken.sol/TestToken.json", "utf8"));
const out =
  "// SPDX-License-Identifier: Apache-2.0\n" +
  "// Generated by scripts/export-abi.ts. Do not edit by hand.\n" +
  `export const spendGuardVaultAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n\n` +
  `export const spendGuardVaultBytecode = ${JSON.stringify(artifact.bytecode)} as const;\n\n` +
  `export const testTokenAbi = ${JSON.stringify(token.abi, null, 2)} as const;\n\n` +
  `export const testTokenBytecode = ${JSON.stringify(token.bytecode)} as const;\n`;
writeFileSync("sdk/abi.ts", out);
console.log("wrote sdk/abi.ts");
